import pytest
from string_utils import slugify


def test_slugify_with_empty_string():
    assert slugify("") == ""


def test_slugify_with_only_spaces():
    assert slugify("   ") == ""


def test_slugify_with_only_tabs():
    assert slugify("\t\t\t") == ""


def test_slugify_with_only_newlines():
    assert slugify("\n\n\n") == ""


def test_slugify_with_only_carriage_returns():
