import pytest

from string_utils import truncate_with_ellipsis


def test_truncate_exact_length():
    assert truncate_with_ellipsis("exactly", 7) == "exactly"


def test_truncate_empty_string():
    assert truncate_with_ellipsis("", 5) == ""


def test_truncate_zero_max_len():
    assert truncate_with_ellipsis("anything", 0) == ""


def test_truncate_negative_max_len_raises():
    with pytest.raises(ValueError, match="max_len must be non-negative"):
        truncate_with_ellipsis("test", -1)


def test_truncate_single_char():
    assert truncate_with_ellipsis("a", 1) == "a"


def test_truncate_single_char_max_len_3():
    assert truncate_with_ellipsis("a", 3) == "a"


def test_truncate_single_char_max_len_2():
    assert truncate_with_ellipsis("a", 2) == "a"


def test_truncate_single_char_max_len_1():
    assert truncate_with_ellipsis("a", 1) == "a"

